const CERT_LABEL_MAP = {
  '8264bc83-1d80-47ac-aa6b-ca021ffb4ace': 'BTC',
  '24d9e2c4-42b0-4133-b801-d8cace4600f5': 'UFC',
};

const stripLearningResourceSuffix = (value = '') =>
  String(value)
    .replace(/\s*-\s*LR\s*\(LMS Animation\)\s*$/i, '')
    .replace(/\s*-\s*LR\s*$/i, '')
    .trim();

const normalizeSortKey = (value = '') =>
  stripLearningResourceSuffix(value)
    .toLowerCase()
    .replace(/\s*\/\s*/g, '/')
    .replace(/\s+/g, ' ')
    .trim();

const normalizeModuleSortLabel = (value = '') => {
  const normalized = normalizeSortKey(value);
  if (!normalized) return '';

  if (/\b(bpd|hc)\b/.test(normalized) || /fetal head/.test(normalized)) {
    return 'BPD & HC';
  }
  if (/^ac\b/.test(normalized) || /abdominal circumference/.test(normalized) || /fetal abdomen/.test(normalized)) {
    return 'AC';
  }
  if (/^fl\b/.test(normalized) || /femur/.test(normalized)) {
    return 'FL';
  }
  if (/principles? of ultrasound/.test(normalized)) {
    return 'Principles of ultrasound';
  }
  if (/probe movements?/.test(normalized)) {
    return 'Probe Movements';
  }
  if (/knobology/.test(normalized)) {
    return 'Knobology';
  }
  if (/morphology/.test(normalized)) {
    return 'Morphology';
  }

  return String(value).trim();
};

