const getDisplayResourceName = (moduleLabel, resourceName, topic = '') => {
  if (['AC', 'FL'].includes(normalizeModuleSortLabel(moduleLabel))) {
    return BIOMETRY_RESOURCE_BY_ALIAS[normalizeSortKey(resourceName)] || resourceName;
  }

  if (isPrinciplesOfUltrasoundScope(moduleLabel)) {
    if (
      [normalizeSortKey('Image Optimization Activity'), normalizeSortKey('Image Otimization Activity')].includes(normalizeSortKey(topic)) &&
      normalizeSortKey(resourceName) === normalizeSortKey('Interaction')
    ) {
      return 'Interaction';
    }
    return PRINCIPLES_OF_ULTRASOUND_RESOURCE_BY_ALIAS[normalizeSortKey(resourceName)] || resourceName;
  }

  if (isKnobologyScope(moduleLabel)) {
    return KNOBLOGY_RESOURCE_BY_ALIAS[normalizeSortKey(resourceName)] || resourceName;
  }

  if (isMorphologyScope(moduleLabel)) {
    return MORPHOLOGY_RESOURCE_BY_ALIAS[normalizeSortKey(resourceName)] || resourceName;
  }

  if (isProbeMovementsScope(moduleLabel)) {
    const normalizedResource = normalizeSortKey(resourceName);
    if (normalizedResource === normalizeSortKey('Probe Movements')) {
      return normalizeSortKey(topic) === normalizeSortKey('Echo Dose')
        ? 'Probe movements'
        : 'Probe Movements';
    }
    return PROBE_MOVEMENTS_RESOURCE_BY_ALIAS[normalizedResource] || resourceName;
  }

  return resourceName;
};

const getDisplayResourceTopic = (moduleLabel, topic, resourceName) => {
  const normalizedModule = normalizeModuleSortLabel(moduleLabel);
  const normalizedTopic = normalizeSortKey(topic);
  const normalizedResource = normalizeSortKey(resourceName);

  if (normalizedModule === 'Principles of ultrasound') {
    return (
      PRINCIPLES_OF_ULTRASOUND_TOPIC_BY_ALIAS[normalizedTopic] ||
      PRINCIPLES_OF_ULTRASOUND_TOPIC_BY_ALIAS[normalizedResource] ||
      topic
    );
  }

  if (normalizedModule === 'Knobology') {
    return KNOBLOGY_TOPIC_BY_RESOURCE[normalizedResource] || topic;
  }

  if (normalizedModule === 'Morphology') {
    return MORPHOLOGY_TOPIC_BY_RESOURCE[normalizedResource] || topic;
  }

  if (normalizedModule === 'Probe Movements') {
    if (
      normalizedResource === normalizeSortKey('Probe Movements') &&
      normalizedTopic === normalizeSortKey('Echo Dose')
    ) {
      return 'Echo Dose';
    }
    return PROBE_MOVEMENTS_TOPIC_BY_RESOURCE[normalizedResource] || topic;
  }

  if (normalizedModule === 'AC') {
    if (
      normalizedResource === normalizeSortKey('MindSparks - Picture Pick') ||
      normalizedResource === normalizeSortKey('Mind Sparks - Picture Pick')
    ) {
      return normalizedTopic.includes('pitfall') || normalizedTopic.includes('plane acquisition')
        ? 'Pitfalls in Plane Acquisition and Measurement'
        : 'Measurement';
    }

    return AC_TOPIC_BY_RESOURCE[normalizedResource] || topic;
  }

  // BPD & HC names, topics, visibility, and ordering are maintained in the
  // database. Do not remap them in the client.
  return topic;
};

