const parseValidDate = value => {
  if (value === null || value === undefined) return null;

  const normalizedValue = typeof value === 'string' ? value.trim() : value;
  if (
    normalizedValue === '' ||
    (typeof normalizedValue === 'string' && ['n/a', 'null', 'undefined', 'invalid date'].includes(normalizedValue.toLowerCase()))
  ) {
    return null;
  }

  try {
    const date = normalizedValue instanceof Date ? normalizedValue : new Date(normalizedValue);
    return Number.isNaN(date.getTime()) ? null : date;
  } catch {
    return null;
  }
};

const formatDate = value => {
  const date = parseValidDate(value);
  return date
    ? date.toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' })
    : '—';
};

const formatDateTime = value => {
  const date = parseValidDate(value);
  return date
    ? date.toLocaleString('en-IN', { day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' })
    : '—';
};

const scoreMeta = pct => {
  if (pct >= 80) return { hex: '#8DC63F', cls: 'text-[#8DC63F]' };
  if (pct >= 50) return { hex: '#F59E0B', cls: 'text-amber-500' };
  return { hex: '#EF4444', cls: 'text-red-500' };
};

const normalizeCertTabLabel = (label = '', certificateId = '') => {
  if (CERT_LABEL_MAP[certificateId]) return CERT_LABEL_MAP[certificateId];

  const normalizedLabel = String(label).trim();
  if (!normalizedLabel) return certificateId;

  if (/\bbtc\b/i.test(normalizedLabel) || /second trimester/i.test(normalizedLabel)) {
    return 'BTC';
  }

  if (
    /\bufc\b/i.test(normalizedLabel) ||
    /probe movements/i.test(normalizedLabel) ||
    /principles? of ultrasound/i.test(normalizedLabel)
  ) {
    return 'UFC';
  }

  return normalizedLabel;
};

