// ─── DATA TRANSFORMATION ──────────────────────────────────────────────────────

/**
 * batchCert: { certId, certName } | null
 *
 * The trainee API returns ALL certificates the trainee is enrolled in across
 * the whole platform (e.g. BTC + "Principle of Ultrasound"). We only want the
 * one belonging to this batch, so we filter rawData by batchCert.certId first.
 * After that filter, the cert label is simply batchCert.certName — no guessing.
 */
function transformApiData(apiResponse, batchCert = null, batchCertificateIds = [], activityLastScores = []) {
  const { data: rawData = [], reAttempts = [] } = apiResponse;
  const batchCertIds = new Set((batchCert?.certIds || []).filter(Boolean));
  const scopedCertificateIds = new Set((batchCertificateIds || []).filter(Boolean));
  const allowedCertificateIds = batchCertIds.size > 0 ? batchCertIds : scopedCertificateIds;
  const activityScoreMap = new Map(
    (activityLastScores || [])
      .filter(row => row?.resource_id)
      .map(row => [row.resource_id, row])
  );

  // ── Filter to batch certificate only ─────────────────────────────────────
  const data = allowedCertificateIds.size > 0
    ? rawData.filter(item =>
      allowedCertificateIds.has(item.certificate_id) &&
      item.is_hidden !== true
    )
    : [];

  // ── Re-attempt lookup ─────────────────────────────────────────────────────
  const reAttemptMap = {};
  reAttempts.forEach(ra => {
    if (!ra.resource_id) return;
    if (!reAttemptMap[ra.resource_id]) reAttemptMap[ra.resource_id] = [];
    reAttemptMap[ra.resource_id].push(ra);
  });

  // ── Completion lookup ─────────────────────────────────────────────────────
  const completionMap = {};
  data.forEach(item => {
    if (item.resource_id) completionMap[item.resource_id] = item.is_completed === true;
  });

  // ── Unique certificates ───────────────────────────────────────────────────
  const certOrder = [];
  const certSeen = new Set();
  data.forEach(item => {
    if (!item.certificate_id || certSeen.has(item.certificate_id)) return;
    certSeen.add(item.certificate_id);
    const rawLabel =
      batchCert?.certById?.[item.certificate_id] ??
      item.certificate_name ??
      item.course_name ??
      item.certificate_id;
    certOrder.push({
      id: item.certificate_id,
      label: normalizeCertTabLabel(rawLabel, item.certificate_id),
    });
  });

  // ── Modules grouped by certificate ───────────────────────────────────────
  const modulesByCert = {};
  const resourcesByLMID = {};

  data.forEach(item => {
    const { certificate_id, learning_module_id, unit_name, course_name } = item;

    if (!modulesByCert[certificate_id]) modulesByCert[certificate_id] = new Map();
    const certModules = modulesByCert[certificate_id];

    if (!certModules.has(learning_module_id)) {
      certModules.set(learning_module_id, {
        id: learning_module_id,
        label: unit_name || course_name || learning_module_id,
        locked: false, hasAnyResource: false, done: 0, total: 0,
      });
    }

    if (item.resource_id) certModules.get(learning_module_id).hasAnyResource = true;
    if (!item.resource_id) return;

    if (!resourcesByLMID[learning_module_id]) resourcesByLMID[learning_module_id] = [];
    if (resourcesByLMID[learning_module_id].some(r => r.id === item.resource_id)) return;

    const typeKey = getResourceTypeKey(item.resource_type);
    const moduleLabel = normalizeModuleSortLabel(unit_name || course_name || '');
    const resourceName = (item.resource_name || '').trim();
    const displayResourceName = getDisplayResourceName(moduleLabel, resourceName, item.resource_topic || '');
    const resourceTopic = getDisplayResourceTopic(moduleLabel, item.resource_topic || '', resourceName);
    const completionSource = typeKey === 'resource'
      ? deriveCompletionSource(displayResourceName, resourceTopic)
      : typeKey === 'challenge'
        ? 'activity'
        : null;
    const isDone = completionMap[item.resource_id] === true;
    const activityScore = activityScoreMap.get(item.resource_id);
    const isMindSparkResource = isMindSpark(item.resource_name || '');

    const resourceRow = {
      id: item.resource_id,
      certificateId: certificate_id,
      learningModuleId: learning_module_id,
      name: displayResourceName,
      type: typeKey,
      topic: resourceTopic,
      unit_name: item.unit_name || item.course_name || '',
      module_name: item.module_name || item.unit_name || '',
      course_name: item.course_name || '',
      moduleLabel,
      displayOrder: item.display_order ?? null,
      completionSource,
      done: isDone,
      updatedAt: item.updated_at || null,
      reAttempts: reAttemptMap[item.resource_id] || [],
      activityData: completionSource === 'activity'
        ? {
          attempts: activityScore
            ? Number(activityScore.attempt_count || 1)
            : (isMindSparkResource ? 0 : (isDone ? 1 : 0)),
          correct: activityScore
            ? Number(activityScore.correct_answers || 0)
            : (isMindSparkResource ? 0 : (isDone ? 1 : 0)),
          wrong: activityScore ? Number(activityScore.wrong_answers || 0) : 0,
          total: activityScore
            ? Number(activityScore.total_questions || 0)
            : (isMindSparkResource ? 0 : (isDone ? 1 : 0)),
          scorePercentage: activityScore?.score_percentage !== null && activityScore?.score_percentage !== undefined
            ? Number(activityScore.score_percentage)
            : (isMindSparkResource ? null : (isDone ? 100 : null)),
          sessionDate: activityScore?.session_date || null,
          sessionId: activityScore?.session_id || null,
          resourceId: activityScore?.resource_id || item.resource_id,
          resourceType: activityScore?.resource_type || item.resource_type || null,
          resourceTopic: activityScore?.resource_topic || item.resource_topic || '',
          configuredQuestionCount: Number(activityScore?.configured_question_count || 0),
        }
        : undefined,
    };

    const duplicateResource = resourcesByLMID[learning_module_id].find(r =>
      r.type === resourceRow.type &&
      normalizeSortKey(r.topic) === normalizeSortKey(resourceRow.topic) &&
      normalizeSortKey(r.name) === normalizeSortKey(resourceRow.name)
    );

    if (duplicateResource) {
      duplicateResource.done = duplicateResource.done || resourceRow.done;
      duplicateResource.updatedAt = [duplicateResource.updatedAt, resourceRow.updatedAt].filter(Boolean).sort().pop() || null;
      duplicateResource.reAttempts = [...(duplicateResource.reAttempts || []), ...(resourceRow.reAttempts || [])];
      const resourceAttempts = resourceRow.activityData?.attempts || 0;
      const duplicateAttempts = duplicateResource.activityData?.attempts || 0;
      const resourceSessionDate = Date.parse(resourceRow.activityData?.sessionDate || '') || 0;
      const duplicateSessionDate = Date.parse(duplicateResource.activityData?.sessionDate || '') || 0;
      if (
        resourceAttempts > duplicateAttempts ||
        (resourceAttempts === duplicateAttempts && resourceSessionDate > duplicateSessionDate)
      ) {
        duplicateResource.activityData = resourceRow.activityData;
      }
      return;
    }

    resourcesByLMID[learning_module_id].push(resourceRow);
  });

  // ── Sort modules per certificate ──────────────────────────────────────────
  const modulesByCertFinal = {};
  certOrder.forEach(cert => {
    const modMap = modulesByCert[cert.id];
    if (!modMap) { modulesByCertFinal[cert.id] = []; return; }
    modulesByCertFinal[cert.id] = Array.from(modMap.values())
      .map(mod => ({ ...mod, locked: !mod.hasAnyResource }))
      .sort((a, b) => {
        const ai = MODULE_ORDER.indexOf(normalizeModuleSortLabel(a.label));
        const bi = MODULE_ORDER.indexOf(normalizeModuleSortLabel(b.label));
        return (ai === -1 ? 999 : ai) - (bi === -1 ? 999 : bi);
      });
  });

  // ── Sort resources within each module ────────────────────────────────────
  const sortedResources = {};
  Object.entries(resourcesByLMID).forEach(([lmid, items]) => {
    let unitName = '';
    Object.values(modulesByCertFinal).forEach(mods =>
      mods.forEach(m => { if (m.id === lmid) unitName = m.label; })
    );
    const normalizedUnitName = normalizeModuleSortLabel(unitName);
    sortedResources[lmid] = [...items].sort((a, b) => {
      const aTopicOrder = a.type === 'resource' ? getTopicSortIndex(normalizedUnitName, a.topic) : 999;
      const bTopicOrder = b.type === 'resource' ? getTopicSortIndex(normalizedUnitName, b.topic) : 999;

      if (aTopicOrder !== bTopicOrder) {
        return aTopicOrder - bTopicOrder;
      }

      const pa = a.type === 'resource'
        ? getResourceSortIndex(normalizedUnitName, a.name, a.displayOrder, a.topic)
        : (NON_RESOURCE_ORDER[a.type]?.[normalizeSortKey(a.name)] ?? 999);
      const pb = b.type === 'resource'
        ? getResourceSortIndex(normalizedUnitName, b.name, b.displayOrder, b.topic)
        : (NON_RESOURCE_ORDER[b.type]?.[normalizeSortKey(b.name)] ?? 999);
      return pa - pb;
    });
  });

  // ── Compute done / total counts per module ────────────────────────────────
  Object.values(modulesByCertFinal).forEach(mods => {
    mods.forEach(mod => {
      const res = sortedResources[mod.id] || [];
      mod.total = res.length;
      mod.done = res.filter(isResourceDone).length;
    });
  });

  return { certs: certOrder, modules: modulesByCertFinal, resources: sortedResources };
}

// ─── SUBMISSION HELPERS ───────────────────────────────────────────────────────

const getConfiguredAnswerKey = answer => String(
  answer?.key ?? answer?.value ?? answer?.answer ?? answer?.option ?? answer?.label ?? ''
);

const normalizeAnswerValue = value => String(value ?? '').trim().toLowerCase();

const getLeadingAnswerToken = value => {
  const normalizedValue = normalizeAnswerValue(value);
  const markerMatch = normalizedValue.match(/^([a-z]|\d{1,3})\s*[-).:]\s*/);
  return markerMatch?.[1] || normalizedValue;
};

const optionMatchesConfiguredKey = (option, answer, optionIndex) => {
  const normalizedAnswer = normalizeAnswerValue(answer);
  if (!normalizedAnswer) return false;

  const answerToken = getLeadingAnswerToken(normalizedAnswer);
  const indexToken = optionIndex !== undefined ? String(optionIndex + 1) : '';
  const optionValues = [option?.key, option?.value, option?.label, option?.text, indexToken]
    .map(normalizeAnswerValue)
    .filter(Boolean);

  return optionValues.some(optionValue =>
    optionValue === normalizedAnswer ||
    getLeadingAnswerToken(optionValue) === answerToken
  );
};

const getConfiguredOptionDetails = (options, key) => {
  return (Array.isArray(options) ? options : []).find((item, index) =>
    optionMatchesConfiguredKey(item, key, index)
  ) || null;
};

const getConfiguredOptionText = (options, key) => {
  const option = getConfiguredOptionDetails(options, key);
  return option?.text ?? option?.label ?? option?.value ?? '';
};

const groupQuestionsByType = (rows) => {
  const byType = {};
  (Array.isArray(rows) ? rows : []).forEach((row) => {
    const type = row.question_type || 'unknown';
    if (!byType[type]) byType[type] = [];
    byType[type].push(row);
  });
  return byType;
};

const getConfiguredAnswerTimeframe = answer => String(
  answer?.timeframe ?? answer?.expected_timeframe ?? ''
).trim();

const getQuestionMetadataList = (metadata, key) => {
  const value = metadata?.[key];
  if (Array.isArray(value)) return value.filter(Boolean);
  if (typeof value === 'string') {
    return value.split(',').map(item => item.trim()).filter(Boolean);
  }
  return [];
};

