function MindSparkAttemptDetailsPanel({ r, token }) {
  const [loading, setLoading] = React.useState(true);
  const [error, setError] = React.useState(null);
  const [details, setDetails] = React.useState([]);
  const [summary, setSummary] = React.useState(null);
  const isOBResource = isOBBooster(r.topic);
  const activityLabel = isOBResource ? 'OB Booster' : 'Mindspark';
  const attemptResourceId = r.activityData?.resourceId || r.id;

  React.useEffect(() => {
    let active = true;
    setLoading(true);
    setError(null);

    fetchMindSparkAttemptDetails(attemptResourceId, token, r.activityData?.sessionId)
      .then(json => {
        if (!active) return;
        setDetails(Array.isArray(json?.data) ? json.data : []);
        setSummary(json?.summary || null);
      })
      .catch(err => {
        if (active) setError(err.message);
      })
      .finally(() => {
        if (active) setLoading(false);
      });

    return () => {
      active = false;
    };
  }, [attemptResourceId, r.activityData?.sessionId, token]);

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12 text-gray-400">
        <Loader2 size={22} className="animate-spin mr-2" />
        <span className="text-sm">Loading {activityLabel} details...</span>
      </div>
    );
  }

  if (error) {
    return (
      <div className="rounded-xl border border-red-100 bg-red-50 px-4 py-3 text-sm text-red-500">
        {error}
      </div>
    );
  }

  if (!details.length) {
    return (
      <div className="flex flex-col items-center justify-center py-10 text-gray-400">
        <Zap size={28} className="mb-2 text-gray-300" />
        <p className="text-sm font-medium">No {activityLabel} attempt found</p>
        <p className="text-xs mt-1">This resource has no mapped attempt details yet</p>
      </div>
    );
  }

  const correct = Number(summary?.correct_answers || 0);
  const total = Number(summary?.total_questions || details.length);
  const wrong = Number(summary?.wrong_answers || 0);
  const pct = summary?.score_percentage !== null && summary?.score_percentage !== undefined
    ? Number(summary.score_percentage)
    : (total > 0 ? (correct / total) * 100 : null);

  return (
    <div className="space-y-3">
      <div className="grid grid-cols-2 md:grid-cols-4 gap-2">
        <div className="rounded-lg border border-gray-100 bg-white px-3 py-2">
          <p className="text-[10px] text-gray-400">Score</p>
          <p className="text-sm font-semibold text-gray-700">{pct !== null ? `${Math.round(pct)}%` : '—'}</p>
        </div>
        <div className="rounded-lg border border-gray-100 bg-white px-3 py-2">
          <p className="text-[10px] text-gray-400">Correct</p>
          <p className="text-sm font-semibold text-[#8DC63F]">{correct}</p>
        </div>
        <div className="rounded-lg border border-gray-100 bg-white px-3 py-2">
          <p className="text-[10px] text-gray-400">Wrong</p>
          <p className="text-sm font-semibold text-red-500">{wrong}</p>
        </div>
        <div className="rounded-lg border border-gray-100 bg-white px-3 py-2">
          <p className="text-[10px] text-gray-400">Questions</p>
          <p className="text-sm font-semibold text-gray-700">{total}</p>
        </div>
      </div>

      {details.map((item, index) => {
        const options = Array.isArray(item.options) ? item.options : [];
        const correctKey = getMindSparkAnswerKey(item.correct_answer);
        const selectedText = getMindSparkOptionText(options, item.option_chosen);
        const correctText = getMindSparkOptionText(options, correctKey);
        const answered = item.is_correct === true || item.is_correct === false;
        const right = item.is_correct === true;
        const selectedKey = String(item.option_chosen ?? '');

        return (
          <div
            key={item.question_id || `${item.question_no}-${index}`}
            className={`rounded-xl border bg-white p-3 ${right ? 'border-[#8DC63F]/40' : answered ? 'border-red-200' : 'border-gray-200'}`}
          >
            <div className="flex items-start gap-3">
              <div className={`w-7 h-7 rounded-full flex items-center justify-center flex-shrink-0 ${right ? 'bg-[#8DC63F]/10 text-[#8DC63F]' : answered ? 'bg-red-50 text-red-500' : 'bg-gray-100 text-gray-400'
                }`}>
                {right ? <CheckCircle2 size={15} /> : answered ? <X size={15} /> : item.question_no || index + 1}
              </div>
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2 mb-1">
                  <span className={`text-[10px] font-semibold px-2 py-0.5 rounded-full ${right ? 'bg-[#8DC63F]/10 text-[#8DC63F]' : answered ? 'bg-red-50 text-red-500' : 'bg-gray-100 text-gray-400'
                    }`}>
                    {right ? 'Right' : answered ? 'Wrong' : 'Not answered'}
                  </span>
                  <span className="text-[10px] text-gray-400">Question {item.question_no || index + 1}</span>
                </div>
                <p className="text-sm font-semibold text-gray-800">{item.prompt}</p>
                {item.assets?.length > 0 && (
                  <div className="mt-3 grid grid-cols-2 gap-2">
                    {item.assets.map((asset, assetIndex) => (
                      <div key={assetIndex} className="rounded-lg border border-gray-100 bg-gray-50 overflow-hidden">
                        {asset.url ? (
                          <img src={asset.url} alt={asset.alt || `Question asset ${assetIndex + 1}`} className="w-full max-h-44 object-contain" />
                        ) : (
                          <div className="p-2 text-[11px] text-gray-500 break-all">{asset.name || JSON.stringify(asset)}</div>
                        )}
                      </div>
                    ))}
                  </div>
                )}
                {options.length > 0 && (
                  <div className="mt-3 grid gap-2">
                    {options.map((option, optionIndex) => {
                      const optionKey = String(option.key ?? option.value ?? optionIndex + 1);
                      const optionText = option.text ?? option.label ?? String(option);
                      const optionImageUrl = option.image_url ?? option.imageUrl ?? option.url ?? option.asset_url;
                      const selected = answered && optionMatchesConfiguredKey(option, selectedKey);
                      const correctOption = optionMatchesConfiguredKey(option, correctKey);

                      return (
                        <div
                          key={`${item.question_id || item.question_no}-${optionKey}`}
                          className={`rounded-lg border px-3 py-2 text-xs ${selected
                              ? right
                                ? 'border-[#8DC63F]/50 bg-[#8DC63F]/5'
                                : 'border-red-200 bg-red-50'
                              : correctOption
                                ? 'border-[#8DC63F]/30 bg-[#8DC63F]/5'
                                : 'border-gray-100 bg-gray-50'
                            }`}
                        >
                          <div className="flex items-center justify-between gap-2">
                            <span className="font-medium text-gray-700">
                              <span className="mr-2">{optionKey}.</span>
                              {optionText && optionText !== '[object Object]' ? optionText : ''}
                            </span>
                            <div className="flex gap-1">
                              {selected && <span className="rounded-full bg-gray-900/5 px-2 py-0.5 text-[10px] text-gray-600">Selected</span>}
                              {correctOption && <span className="rounded-full bg-[#8DC63F]/10 px-2 py-0.5 text-[10px] text-[#5d8f20]">Correct</span>}
                            </div>
                          </div>
                          {optionImageUrl && (
                            <div className="mt-2 h-28 rounded-md bg-white overflow-hidden flex items-center justify-center">
                              <img src={optionImageUrl} alt={option.image_alt || optionText || `Option ${optionKey}`} className="h-full w-full object-contain" />
                            </div>
                          )}
                        </div>
                      );
                    })}
                  </div>
                )}
                <div className="mt-3 grid gap-2 text-xs">
                  <div className="rounded-lg border border-gray-100 bg-gray-50 px-3 py-2">
                    <span className="text-gray-400">Selected: </span>
                    <span className={right ? 'font-semibold text-[#8DC63F]' : answered ? 'font-semibold text-red-500' : 'font-semibold text-gray-500'}>
                      {answered ? (selectedText || item.option_chosen || '—') : '—'}
                    </span>
                  </div>
                  <div className="rounded-lg border border-gray-100 bg-gray-50 px-3 py-2">
                    <span className="text-gray-400">Correct answer: </span>
                    <span className="font-semibold text-gray-700">{correctText || correctKey || '—'}</span>
                  </div>
                </div>
                {(right ? item.feedback_correct : item.feedback_wrong) && (
                  <p className="mt-2 text-xs text-gray-500">{right ? item.feedback_correct : item.feedback_wrong}</p>
                )}
              </div>
            </div>
          </div>
        );
      })}
    </div>
  );
}

function ActivityAttemptPanel({ r, token }) {
  if (isMindSpark(r.name) || isOBBooster(r.topic)) {
    return <MindSparkAttemptDetailsPanel r={r} token={token} />;
  }

  const activity = r.activityData || {};
  const attempts = Number(activity.attempts || 0);
  const correct = Number(activity.correct || 0);
  const wrong = Number(activity.wrong || 0);
  const total = Number(activity.total || 0);
  const scorePercentage = activity.scorePercentage;

  if (attempts === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-10 text-gray-400">
        <Zap size={28} className="mb-2 text-gray-300" />
        <p className="text-sm font-medium">No activity attempt found</p>
        <p className="text-xs mt-1">This resource has not been attempted yet</p>
      </div>
    );
  }

  return (
    <div className="border border-gray-100 rounded-xl bg-gray-50/60 overflow-hidden">
      <div className="flex items-center gap-4 px-4 py-2.5 bg-white border-b border-gray-100 text-xs text-gray-500">
        <div className="flex items-center gap-1.5">
          <Target size={12} className="text-[#8DC63F]" />
          <span><span className="font-semibold text-gray-700">{correct}</span>/<span className="font-semibold text-gray-700">{total}</span> correct</span>
        </div>
        <div className="flex items-center gap-1.5">
          <History size={12} className="text-slate-500" />
          <span><span className="font-semibold text-gray-700">{attempts}</span> attempt{attempts !== 1 ? 's' : ''}</span>
        </div>
        {activity.sessionDate && (
          <div className="flex items-center gap-1.5 ml-auto">
            <Calendar size={11} className="text-gray-400" />
            <span>Last: {formatDate(activity.sessionDate)}</span>
          </div>
        )}
      </div>

      <div className="p-3 space-y-3">
        <div className="grid grid-cols-2 md:grid-cols-4 gap-2">
          <div className="rounded-lg border border-gray-100 bg-white px-3 py-2">
            <p className="text-[10px] text-gray-400">Score</p>
            <p className="text-sm font-semibold text-gray-700">
              {scorePercentage !== null && scorePercentage !== undefined ? `${Math.round(scorePercentage)}%` : '—'}
            </p>
          </div>
          <div className="rounded-lg border border-gray-100 bg-white px-3 py-2">
            <p className="text-[10px] text-gray-400">Correct</p>
            <p className="text-sm font-semibold text-[#8DC63F]">{correct}</p>
          </div>
          <div className="rounded-lg border border-gray-100 bg-white px-3 py-2">
            <p className="text-[10px] text-gray-400">Wrong</p>
            <p className="text-sm font-semibold text-red-500">{wrong}</p>
          </div>
          <div className="rounded-lg border border-gray-100 bg-white px-3 py-2">
            <p className="text-[10px] text-gray-400">Questions</p>
            <p className="text-sm font-semibold text-gray-700">{total}</p>
          </div>
        </div>

        <div className="rounded-xl border border-blue-100 bg-blue-50/40 px-3 py-3">
          <div className="flex items-center gap-2 mb-2">
            {isMindSpark(r.name)
              ? <Zap size={12} className="text-yellow-500" />
              : <Puzzle size={12} className="text-pink-500" />
            }
            <span className="text-xs font-semibold text-gray-600">Latest activity snapshot</span>
          </div>
          <div className="space-y-1.5 text-xs text-gray-600">
            <p>Resource: <span className="font-medium text-gray-700">{r.name}</span></p>
            <p>Topic: <span className="font-medium text-gray-700">{activity.resourceTopic || r.topic || '—'}</span></p>
            <p>Source: <span className="font-medium text-gray-700">{activity.resourceType || 'Activity Submission'}</span></p>
            <p>Session ID: <span className="font-medium text-gray-700 break-all">{activity.sessionId || '—'}</span></p>
            <p>Attempted At: <span className="font-medium text-gray-700">{activity.sessionDate ? formatDateTime(activity.sessionDate) : '—'}</span></p>
          </div>
        </div>
      </div>
    </div>
  );
}

function AttemptHistoryModal({ r, showFeedback, onClose, token, showSubmission }) {
  const meta = TYPE_META[r.type] || TYPE_META.practice;
  const isActivity = r.completionSource === 'activity';

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 backdrop-blur-sm p-4"
      onClick={e => e.target === e.currentTarget && onClose()}
    >
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-2xl max-h-[85vh] flex flex-col overflow-hidden">
        <div className="flex items-center gap-3 px-5 py-4 border-b border-gray-100 flex-shrink-0">
          <div className={`w-9 h-9 rounded-lg border flex items-center justify-center flex-shrink-0 ${meta.bg} ${meta.border}`}>
            <History size={16} className={meta.color} />
          </div>
          <div className="flex-1 min-w-0">
            <h2 className="text-sm font-bold text-gray-800 truncate">{r.name}</h2>
            <p className="text-[11px] text-gray-400 mt-0.5">{isActivity ? 'Activity attempt details' : 'Attempt history'}</p>
          </div>
          <button
            onClick={onClose}
            className="w-8 h-8 rounded-lg flex items-center justify-center hover:bg-gray-100 transition-colors flex-shrink-0"
          >
            <X size={16} className="text-gray-400" />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-5 bg-gray-50">
          {isActivity
            ? <ActivityAttemptPanel r={r} token={token} />
            : <PracticeExpandedPanel r={r} showFeedback={showFeedback} showSubmission={showSubmission} token={token} className="mt-0" />
          }
        </div>
      </div>
    </div>
  );
}

function MindSparkQuizModal({ r, token, onClose }) {
  const [loading, setLoading] = React.useState(true);
  const [error, setError] = React.useState(null);
  const [questions, setQuestions] = React.useState([]);

  React.useEffect(() => {
    let active = true;
    setLoading(true);
    setError(null);

    fetchMindSparkQuestions(r.id, token)
      .then(data => {
        if (active) setQuestions(data);
      })
      .catch(err => {
        if (active) setError(err.message);
      })
      .finally(() => {
        if (active) setLoading(false);
      });

    return () => {
      active = false;
    };
  }, [r.id, token]);

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 backdrop-blur-sm p-4"
      onClick={e => e.target === e.currentTarget && onClose()}
    >
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-3xl max-h-[90vh] flex flex-col overflow-hidden">
        <div className="flex items-center gap-3 px-5 py-4 border-b border-gray-100 flex-shrink-0">
          <div className="w-9 h-9 rounded-lg bg-yellow-50 border border-yellow-200 flex items-center justify-center flex-shrink-0">
            <Zap size={16} className="text-yellow-500" />
          </div>
          <div className="flex-1 min-w-0">
            <h2 className="text-sm font-bold text-gray-800 truncate">{r.name}</h2>
            <p className="text-[11px] text-gray-400 mt-0.5">Mindspark questions</p>
          </div>
          <button
            onClick={onClose}
            className="w-8 h-8 rounded-lg flex items-center justify-center hover:bg-gray-100 transition-colors flex-shrink-0"
          >
            <X size={16} className="text-gray-400" />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto px-5 py-4 space-y-4 bg-gray-50">
          {loading && (
            <div className="flex items-center justify-center py-16 text-gray-400">
              <Loader2 size={24} className="animate-spin mr-2" />
              <span className="text-sm">Loading Mindspark questions...</span>
            </div>
          )}

          {error && !loading && (
            <div className="rounded-xl border border-red-100 bg-red-50 px-4 py-3 text-sm text-red-500">
              {error}
            </div>
          )}

          {!loading && questions.length === 0 && (
            <div className="flex flex-col items-center justify-center py-16 text-gray-400">
              <Zap size={32} className="mb-3 text-gray-300" />
              <p className="text-sm font-medium">No Mindspark questions configured</p>
              <p className="text-xs mt-1">Ask the admin to configure this resource.</p>
            </div>
          )}

          {!loading && questions.map((question, index) => {
            const options = Array.isArray(question.options) ? question.options : [];
            const isOrderingQuestion = String(question.question_type || '').toUpperCase() === 'ORDERING';

            return (
              <div key={question.question_id} className="rounded-xl border border-gray-200 bg-white p-4">
                <div className="flex items-start gap-3">
                  <div className="w-7 h-7 rounded-full bg-yellow-50 border border-yellow-200 text-yellow-600 flex items-center justify-center text-xs font-bold flex-shrink-0">
                    {question.question_no ?? index + 1}
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-semibold text-gray-800">{question.prompt}</p>
                    {question.assets?.length > 0 && (
                      <div className="mt-3 grid grid-cols-2 gap-3">
                        {question.assets.map((asset, assetIndex) => (
                          <div key={assetIndex} className="rounded-lg border border-gray-100 overflow-hidden bg-gray-50">
                            {asset.url ? (
                              <img src={asset.url} alt={asset.alt || `Question asset ${assetIndex + 1}`} className="w-full max-h-56 object-contain bg-black/5" />
                            ) : (
                              <div className="p-3 text-xs text-gray-500 break-all">{asset.name || JSON.stringify(asset)}</div>
                            )}
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                </div>

                <div className="mt-4 space-y-2">
                  {options.length > 0 ? options.map((option, optionIndex) => {
                    const key = String(option.key ?? option.value ?? optionIndex + 1);
                    const optionText = option.text ?? option.label ?? String(option);
                    const optionImageUrl = option.image_url ?? option.imageUrl ?? option.url ?? option.asset_url;
                    const optionImageAlt = option.image_alt ?? option.imageAlt ?? option.alt ?? optionText ?? `Option ${key}`;

                    return (
                      <div
                        key={`${question.question_id}-${key}`}
                        className="w-full rounded-lg border border-gray-100 bg-white px-3 py-2 text-sm text-gray-700"
                      >
                        <div>
                          {!isOrderingQuestion && <span className="font-semibold mr-2">{key}.</span>}
                          {optionText && optionText !== "[object Object]" && <span>{optionText}</span>}
                        </div>
                        {optionImageUrl && (
                          <div className="mt-2 h-36 rounded-md bg-gray-50 overflow-hidden flex items-center justify-center">
                            <img src={optionImageUrl} alt={optionImageAlt} className="h-full w-full object-contain" />
                          </div>
                        )}
                      </div>
                    );
                  }) : (
                    <div className="rounded-lg bg-white px-3 py-2 text-sm text-gray-400">
                      No options configured
                    </div>
                  )}
                </div>
              </div>
            );
          })}
        </div>

        {!loading && questions.length > 0 && (
          <div className="flex items-center justify-between px-5 py-3 border-t border-gray-100 bg-white flex-shrink-0">
            <span className="text-xs text-gray-400">
              {questions.length} question{questions.length !== 1 ? 's' : ''}
            </span>
            <div className="flex items-center gap-2">
              <button
                onClick={onClose}
                className="px-4 py-1.5 rounded-lg border border-gray-200 hover:border-gray-300 transition-colors text-xs font-medium text-gray-500"
              >
                Close
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

function ReattemptLog({ reAttempts, updatedAt }) {
  const attempts = reAttempts.length > 0
    ? reAttempts
    : (updatedAt ? [{ attempted_at: updatedAt, score: null, is_completed: true, attempt_number: 1 }] : []);

  if (attempts.length === 0) {
    return (
      <div className="flex items-center gap-2 text-gray-400 py-2 px-3">
        <History size={13} /><span className="text-xs">No attempt history yet</span>
      </div>
    );
  }

  return (
    <div className="space-y-1.5">
      {attempts.map((attempt, idx) => {
        const attemptNo = attempt.attempt_number ?? (attempts.length - idx);
        const isReattempt = attemptNo > 1;
        const score = attempt.score ?? attempt.percentage ?? null;
        const passed = attempt.is_completed === true || attempt.passed === true;
        return (
          <div key={idx} className={`flex items-center gap-3 px-3 py-2 rounded-lg border text-xs
            ${isReattempt ? 'border-amber-200 bg-amber-50/60' : 'border-gray-100 bg-gray-50'}`}>
            <div className={`w-5 h-5 rounded-full flex items-center justify-center flex-shrink-0 font-bold text-[10px]
              ${passed ? 'bg-[#8DC63F] text-white' : 'bg-red-100 text-red-500'}`}>
              {attemptNo}
            </div>
            <div className="flex-1 min-w-0">
              <span className={`font-medium ${isReattempt ? 'text-amber-700' : 'text-gray-600'}`}>
                {isReattempt ? `Re-attempt ${attemptNo - 1}` : 'First attempt'}
              </span>
              {attempt.attempted_at && (
                <span className="ml-2 text-gray-400">{formatDateTime(attempt.attempted_at)}</span>
              )}
            </div>
            {score !== null && (
              <span className={`font-semibold flex-shrink-0
                ${score >= 80 ? 'text-[#8DC63F]' : score >= 50 ? 'text-amber-500' : 'text-red-500'}`}>
                {score}%
              </span>
            )}
            <div className={`flex items-center gap-1 flex-shrink-0 ${passed ? 'text-[#8DC63F]' : 'text-red-400'}`}>
              {passed
                ? <><CheckCheck size={12} /><span className="text-[10px] font-medium">Pass</span></>
                : <><X size={12} /><span className="text-[10px] font-medium">Fail</span></>
              }
            </div>
          </div>
        );
      })}
    </div>
  );
}

function FeedbackPanel({ reAttempts }) {
  const entries = reAttempts.flatMap(ra => {
    const list = [];
    if (ra.feedback || ra.instructor_feedback || ra.expert_feedback) {
      list.push({
        type: 'text',
        text: ra.feedback || ra.instructor_feedback || ra.expert_feedback,
        by: ra.feedback_by || ra.instructor_name || 'Instructor',
        date: ra.feedback_at || ra.attempted_at,
      });
    }
    if (ra.user_measurement !== undefined || ra.expert_measurement !== undefined) {
      list.push({
        type: 'measurement',
        userValue: ra.user_measurement,
        expertValue: ra.expert_measurement,
        offset: ra.offset,
        unit: ra.unit || 'mm',
        date: ra.attempted_at,
      });
    }
    if (ra.guidance_notes) {
      list.push({
        type: 'guidance',
        notes: Array.isArray(ra.guidance_notes) ? ra.guidance_notes : [ra.guidance_notes],
        date: ra.feedback_at || ra.attempted_at,
      });
    }
    return list;
  });

  if (entries.length === 0) {
    return (
      <div className="flex items-center gap-2 text-gray-400 py-2 px-3">
        <MessageSquare size={13} /><span className="text-xs">No feedback available yet</span>
      </div>
    );
  }

  return (
    <div className="space-y-2">
      {entries.map((entry, idx) => {
        if (entry.type === 'measurement') {
          const off = parseFloat(entry.offset);
          const ok = !isNaN(off) && Math.abs(off) <= 2;
          return (
            <div key={idx} className="border border-purple-100 bg-purple-50/40 rounded-lg p-3">
              <div className="flex items-center gap-1.5 mb-2">
                <Ruler size={12} className="text-purple-500" />
                <span className="text-[11px] font-semibold text-purple-700">Measurement Comparison</span>
                <span className="ml-auto text-[10px] text-gray-400">{formatDate(entry.date)}</span>
              </div>
              <div className="grid grid-cols-3 gap-2 text-center">
                <div className="bg-white rounded-lg px-2 py-1.5 border border-gray-100">
                  <p className="text-[9px] text-gray-400 mb-0.5">Your Measure</p>
                  <p className="text-sm font-bold text-gray-700">
                    {entry.userValue ?? '—'}<span className="text-[10px] font-normal text-gray-400 ml-0.5">{entry.unit}</span>
                  </p>
                </div>
                <div className="bg-white rounded-lg px-2 py-1.5 border border-gray-100">
                  <p className="text-[9px] text-gray-400 mb-0.5">Expert Measure</p>
                  <p className="text-sm font-bold text-[#8DC63F]">
                    {entry.expertValue ?? '—'}<span className="text-[10px] font-normal text-gray-400 ml-0.5">{entry.unit}</span>
                  </p>
                </div>
                <div className={`rounded-lg px-2 py-1.5 border ${ok ? 'bg-green-50 border-green-100' : 'bg-red-50 border-red-100'}`}>
                  <p className="text-[9px] text-gray-400 mb-0.5">Offset</p>
                  <p className={`text-sm font-bold ${ok ? 'text-[#8DC63F]' : 'text-red-500'}`}>
                    {entry.offset !== undefined ? `${entry.offset}${entry.unit}` : '—'}
                  </p>
                </div>
              </div>
            </div>
          );
        }
        if (entry.type === 'text') {
          return (
            <div key={idx} className="border border-blue-100 bg-blue-50/40 rounded-lg p-3">
              <div className="flex items-center gap-1.5 mb-1.5">
                <MessageSquare size={12} className="text-blue-500" />
                <span className="text-[11px] font-semibold text-blue-700">{entry.by}</span>
                <span className="ml-auto text-[10px] text-gray-400">{formatDate(entry.date)}</span>
              </div>
              <p className="text-xs text-gray-600 leading-relaxed">{entry.text}</p>
            </div>
          );
        }
        if (entry.type === 'guidance') {
          return (
            <div key={idx} className="border border-amber-100 bg-amber-50/40 rounded-lg p-3">
              <div className="flex items-center gap-1.5 mb-2">
                <StickyNote size={12} className="text-amber-500" />
                <span className="text-[11px] font-semibold text-amber-700">Guidance Notes</span>
                <span className="ml-auto text-[10px] text-gray-400">{formatDate(entry.date)}</span>
              </div>
              <ul className="space-y-1">
                {entry.notes.map((note, ni) => (
                  <li key={ni} className="flex items-start gap-1.5 text-xs text-gray-600">
                    <span className="mt-0.5 w-1.5 h-1.5 rounded-full bg-amber-400 flex-shrink-0" />{note}
                  </li>
                ))}
              </ul>
            </div>
          );
        }
        return null;
      })}
    </div>
  );
}

function PracticeExpandedPanel({ r, showFeedback, showSubmission = false, token, className = '' }) {
  const practiceNumber = getPracticeNumber(r.name);
  const showVisualization = r.type === 'practice' && (practiceNumber === 1 || practiceNumber === 2);
  const [activeTab, setActiveTab] = React.useState(showVisualization ? 'visualization' : 'log');
  const tabs = [
    { id: 'log', label: 'Attempt Log', icon: History },
    ...(showVisualization ? [{ id: 'visualization', label: 'Visualization', icon: Target }] : []),
    ...(showFeedback ? [{ id: 'feedback', label: 'Feedback', icon: MessageSquare }] : []),
    ...(showSubmission ? [{ id: 'submission', label: 'Submitted Content', icon: FileText }] : []),
  ];
  const totalAttempts = r.reAttempts.length || (r.done ? 1 : 0);
  const reattemptCount = Math.max(0, totalAttempts - 1);

  return (
    <div className={`border border-gray-100 rounded-xl bg-gray-50/60 overflow-hidden ${className}`.trim()}>
      <div className="flex items-center gap-4 px-4 py-2.5 bg-white border-b border-gray-100 text-xs text-gray-500">
        <div className="flex items-center gap-1.5">
          <Target size={12} className="text-[#8DC63F]" />
          <span><span className="font-semibold text-gray-700">{totalAttempts}</span> total attempt{totalAttempts !== 1 ? 's' : ''}</span>
        </div>
        {reattemptCount > 0 && (
          <div className="flex items-center gap-1.5">
            <RotateCcw size={12} className="text-amber-500" />
            <span><span className="font-semibold text-amber-600">{reattemptCount}</span> re-attempt{reattemptCount !== 1 ? 's' : ''}</span>
          </div>
        )}
        {r.updatedAt && (
          <div className="flex items-center gap-1.5 ml-auto">
            <Calendar size={11} className="text-gray-400" />
            <span>Last: {formatDate(r.updatedAt)}</span>
          </div>
        )}
      </div>

      {tabs.length > 1 && (
        <div className="flex border-b border-gray-100 bg-white">
          {tabs.map(tab => {
            const Icon = tab.icon;
            return (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id)}
                className={`flex items-center gap-1.5 px-4 py-2 text-xs font-medium transition-colors border-b-2
                  ${activeTab === tab.id
                    ? 'border-[#8DC63F] text-[#8DC63F] bg-[#8DC63F]/5'
                    : 'border-transparent text-gray-400 hover:text-gray-600'}`}
              >
                <Icon size={12} />{tab.label}
              </button>
            );
          })}
        </div>
      )}

      <div className="p-3">
        {activeTab === 'log' && <ReattemptLog reAttempts={r.reAttempts} updatedAt={r.updatedAt} />}
        {activeTab === 'visualization' && <Practice12VisualizationPanel r={r} token={token} />}
        {activeTab === 'feedback' && <FeedbackPanel reAttempts={r.reAttempts} />}
        {activeTab === 'submission' && <SubmittedContentPanel r={r} token={token} />}
      </div>
    </div>
  );
}

// ─── COMPLETION STATUS ────────────────────────────────────────────────────────

function CompletionStatus({ r }) {
  if (r.completionSource === 'progress') {
    return r.done ? (
      <div className="flex items-center gap-1 text-[#8DC63F] flex-shrink-0">
        <CheckCircle2 size={15} className="fill-[#8DC63F] text-white" />
        <span className="text-[11px] font-semibold">Completed</span>
      </div>
    ) : (
      <span className="text-[10px] text-gray-400 border border-gray-200 rounded-full px-2 py-0.5 flex-shrink-0">
        Not started
      </span>
    );
  }

  if (r.completionSource === 'activity') {
    const { attempts = 0, correct = 0, total = 1 } = r.activityData || {};
    const pct = total > 0 ? Math.round((correct / total) * 100) : 0;
    if (attempts === 0) {
      return (
        <div className="flex items-center gap-1.5 flex-shrink-0">
          {isMindSpark(r.name)
            ? <Zap size={13} className="text-yellow-400" />
            : <Puzzle size={13} className="text-pink-400" />
          }
          <span className="text-[10px] text-gray-400 border border-gray-200 rounded-full px-2 py-0.5">Not attempted</span>
        </div>
      );
    }
    return (
      <div className="flex items-center gap-2 flex-shrink-0">
        <div className="text-right">
          <p className={`text-[11px] font-semibold leading-none ${pct === 100 ? 'text-[#8DC63F]' : 'text-yellow-500'}`}>{correct}/{total}</p>
          <p className="text-[9px] text-gray-400 mt-0.5">{attempts} attempt{attempts !== 1 ? 's' : ''}</p>
        </div>
        <div className="w-12 bg-gray-100 rounded-full h-1.5">
          <div className={`h-1.5 rounded-full transition-all duration-500 ${pct === 100 ? 'bg-[#8DC63F]' : 'bg-yellow-400'}`}
            style={{ width: `${pct}%` }} />
        </div>
        {pct === 100 && <CheckCircle2 size={14} className="fill-[#8DC63F] text-white flex-shrink-0" />}
      </div>
    );
  }

  return r.done ? (
    <div className="flex items-center gap-1 text-[#8DC63F] flex-shrink-0">
      <CheckCircle2 size={15} className="fill-[#8DC63F] text-white" />
      <span className="text-[11px] font-semibold">Completed</span>
    </div>
  ) : (
    <ChevronRight size={16} className="text-gray-300 group-hover:text-[#8DC63F] transition-colors flex-shrink-0" />
  );
}

